#!/usr/bin/env python3
"""OmniPath evidence replay.

Reads one JSON document describing a multipath routing DAG plus a bounded list
of probe rounds, replays the abstract PING/ACK cache model as a discrete event
simulation, and classifies observable telemetry signatures with deterministic
evidence bounds.  Standard library only.
"""

import heapq
import json
import re
import sys

MAX_INPUT_BYTES = 2097152
MAX_PATHS = 8192

# Event priorities within one timestamp (lower runs first).
PRIO_RELEASE = 1
PRIO_PING = 2
PRIO_ACK = 3
PRIO_TIMEOUT = 4
PRIO_HOSTACK = 5

_LABEL_RE = re.compile(r"[a-z0-9]{1,8}\Z", re.ASCII)


class _Invalid(Exception):
    """Raised whenever the input document violates the contract."""


def _invalid():
    sys.stdout.write('{"error":"invalid-input"}\n')
    sys.stdout.flush()
    raise SystemExit(2)


def _pairs_hook(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise _Invalid("duplicate object key")
        obj[key] = value
    return obj


def _constant_hook(_name):
    raise _Invalid("non-finite constant")


def _parse(root):
    """Validate the root document and return normalized model inputs."""
    if type(root) is not dict:
        raise _Invalid("root")
    if set(root) != {"version", "n", "capacity", "edges", "rounds"}:
        raise _Invalid("root keys")
    version = root["version"]
    if type(version) is not int or version != 1:
        raise _Invalid("version")
    n = root["n"]
    if type(n) is not int or n < 2 or n > 96:
        raise _Invalid("n")
    capacity = root["capacity"]
    if type(capacity) is not list or len(capacity) != n:
        raise _Invalid("capacity")
    for value in capacity:
        if type(value) is not int or value < 0 or value > 48:
            raise _Invalid("capacity entry")
    edges = root["edges"]
    if type(edges) is not list or len(edges) > 384:
        raise _Invalid("edges")
    ne = len(edges)
    e_u = []
    e_v = []
    e_ping = []
    e_ack = []
    e_label = []
    seen_pairs = set()
    for edge in edges:
        if type(edge) is not dict:
            raise _Invalid("edge")
        if set(edge) != {"u", "v", "ping_us", "ack_us", "label"}:
            raise _Invalid("edge keys")
        u = edge["u"]
        v = edge["v"]
        ping = edge["ping_us"]
        ack = edge["ack_us"]
        label = edge["label"]
        if type(u) is not int or type(v) is not int or not 0 <= u < v < n:
            raise _Invalid("edge endpoints")
        if type(ping) is not int or not 1 <= ping <= 10000:
            raise _Invalid("ping_us")
        if type(ack) is not int or not 1 <= ack <= 10000:
            raise _Invalid("ack_us")
        if type(label) is not str or _LABEL_RE.match(label) is None:
            raise _Invalid("label")
        pair = (u, v)
        if pair in seen_pairs:
            raise _Invalid("duplicate edge")
        seen_pairs.add(pair)
        e_u.append(u)
        e_v.append(v)
        e_ping.append(ping)
        e_ack.append(ack)
        e_label.append(label)
    rounds = root["rounds"]
    if type(rounds) is not list or len(rounds) > 48:
        raise _Invalid("rounds")
    parsed_rounds = []
    for rnd in rounds:
        if type(rnd) is not dict:
            raise _Invalid("round")
        if set(rnd) != {
            "launch_us",
            "timeout_us",
            "host_delay_us",
            "drop_host_ack",
            "drop_ping",
            "drop_ack",
        }:
            raise _Invalid("round keys")
        launch = rnd["launch_us"]
        timeout = rnd["timeout_us"]
        host_delay = rnd["host_delay_us"]
        drop_host_ack = rnd["drop_host_ack"]
        drop_ping = rnd["ping_drop"] if False else rnd["drop_ping"]
        drop_ack = rnd["drop_ack"]
        if type(launch) is not int or not 0 <= launch <= 1000000000:
            raise _Invalid("launch_us")
        if type(timeout) is not int or not 1 <= timeout <= 1000000:
            raise _Invalid("timeout_us")
        if type(host_delay) is not int or not 1 <= host_delay <= 10000:
            raise _Invalid("host_delay_us")
        if type(drop_host_ack) is not bool:
            raise _Invalid("drop_host_ack")
        if type(drop_ping) is not list or type(drop_ack) is not list:
            raise _Invalid("drop lists")
        set_ping = set()
        for value in drop_ping:
            if type(value) is not int or not 0 <= value < ne or value in set_ping:
                raise _Invalid("drop_ping entry")
            set_ping.add(value)
        set_ack = set()
        for value in drop_ack:
            if type(value) is not int or not 0 <= value < ne or value in set_ack:
                raise _Invalid("drop_ack entry")
            set_ack.add(value)
        parsed_rounds.append((launch, timeout, host_delay, drop_host_ack, set_ping, set_ack))
    return n, capacity, e_u, e_v, e_ping, e_ack, e_label, parsed_rounds


class _Entry(object):
    """One allocated cache entry for a (round, node) key."""

    __slots__ = ("parents", "credited", "proof", "finalized", "complete")

    def __init__(self, parent):
        self.parents = set()
        if parent is not None:
            self.parents.add(parent)
        self.credited = {}
        self.proof = set()
        self.finalized = False
        self.complete = False


def _replay(n, capacity, e_u, e_v, e_ping, e_ack, rounds, out_edges, outdeg, deadlines):
    """Run the discrete-event replay and return instrumentation."""
    nr = len(rounds)
    entries = [dict() for _ in range(nr)]
    node_use = [0] * n
    node_peak = [0] * n
    total_use = 0
    total_peak = 0

    m_net_ping_tx = 0
    m_net_ack_tx = 0
    m_host_ack_tx = 0
    m_dedup = 0
    m_cap_drops = 0
    m_late_ping = 0
    m_ignored_ack = 0
    m_allocations = 0

    started = [False] * nr
    final_us = [None] * nr
    final_complete = [None] * nr
    source_proof = [None] * nr
    host_delivery = [None] * nr

    heap = []
    heappush = heapq.heappush
    heappop = heapq.heappop
    seq = [0]

    def add(time, prio, rnd, key, data):
        seq[0] += 1
        heappush(heap, (time, prio, rnd, key, seq[0], data))

    def finalize(time, rnd, node, entry, complete):
        nonlocal m_host_ack_tx, m_net_ack_tx
        entry.finalized = True
        entry.complete = complete
        frozen = tuple(sorted(entry.proof))
        payload = (frozen, complete)
        if node == 0:
            final_us[rnd] = time
            final_complete[rnd] = complete
            source_proof[rnd] = entry.proof
            m_host_ack_tx += 1
            if not rounds[rnd][3]:
                add(time + rounds[rnd][2], PRIO_HOSTACK, rnd, -1, None)
        parents = entry.parents
        if parents:
            drop_ack = rounds[rnd][5]
            for parent in parents:
                m_net_ack_tx += 1
                if parent not in drop_ack:
                    add(time + e_ack[parent], PRIO_ACK, rnd, parent, payload)
        entry.parents = ()

    for rnd in range(nr):
        add(rounds[rnd][0], PRIO_PING, rnd, -1, None)
        add(deadlines[rnd] + 1, PRIO_RELEASE, rnd, -1, None)

    last_us = 0
    while heap:
        time, prio, rnd, key, _seq, data = heappop(heap)
        last_us = time
        if prio == PRIO_PING:
            if key < 0:
                node = 0
                parent = None
            else:
                node = e_v[key]
                parent = key
            if time > deadlines[rnd]:
                m_late_ping += 1
                continue
            entry = entries[rnd].get(node)
            if entry is not None:
                m_dedup += 1
                if parent is not None:
                    if entry.finalized:
                        m_net_ack_tx += 1
                        if parent not in rounds[rnd][5]:
                            add(
                                time + e_ack[parent],
                                PRIO_ACK,
                                rnd,
                                parent,
                                (tuple(sorted(entry.proof")), entry.complete),
                            )
                    else:
                        entry.parents.add(parent)
                continue
            if node_use[node] >= capacity[node]:
                m_cap_drops += 1
                continue
            entry = _Entry(parent)
            entries[rnd][node] = entry
            node_use[node] += 1
            total_use += 1
            if node_use[node] > node_peak[node]:
                node_peak[node] = node_use[node]
            if total_use > total_peak:
                total_peak = total_use
            m_allocations += 1
            if node == 0:
                started[rnd] = True
            add(deadlines[rnd], PRIO_TIMEOUT, rnd, node, None)
            outs = out_edges[node]
            if outs:
                drop_ping = rounds[rnd][4]
                for oe in outs:
                    m_net_ping_tx += 1
                    if oe not in drop_ping:
                        add(time + e_ping[oe], PRIO_PING, rnd, oe, None)
            else:
                finalize(time, rnd, node, entry, True)
        elif prio == PRIO_ACK:
            node = e_u[key]
            entry = entries[rnd].get(node)
            if entry is None or entry.finalized or key in entry.credited:
                m_ignored_ack += 1
                continue
            entry.credited[key] = data[1]
            carried = data[0]
            if carried:
                entry.proof.update(carried)
            entry.proof.add(key)
            if len(entry.credited) == outdeg[node]:
                finalize(
                    time, rnd, node, entry, all(entry.credited.values())
                )
        elif prio == PRIO_TIMEOUT:
            entry = entries[rnd].get(key)
            if entry is not None and not entry.finalized:
                finalize(time, rnd, key, entry, False)
        elif prio == PRIO_HOSTACK:
            host_delivery[rnd] = time
        else:
            round_entries = entries[rnd]
            if round_entries:
                for node in round_entries:
                    node_use[node] -= 1
                    total_use -= 1
                entries[rnd] = {}

    metrics = {
        "host_probe_tx": nr,
        "network_ping_tx": m_net_ping_tx,
        "network_ack_tx": m_net_ack_tx,
        "host_ack_tx": m_host_ack_tx,
        "deduplicated_ping": m_dedup,
        "capacity_drops": m_cap_drops,
        "late_ping": m_late_ping,
        "ignored_ack": m_ignored_ack,
        "allocations": m_allocations,
        "cache_peak": node_peak,
        "peak_entries": total_peak,
        "end_us": last_us if nr else 0,
    }
    state = {
        "started": started,
        "final_us": final_us,
        "final_complete": final_complete,
        "source_proof": source_proof,
        "host_delivery": host_delivery,
    }
    return metrics, state


def _enumerate_paths(n, out_edges, e_v):
    """All source-to-destination edge-ID paths in the full graph (mask, path)."""
    reach = [False] * n
    reach[n - 1] = True
    for v in range(n - 2, -1, -1):
        for oe in out_edges[v]:
            if reach[e_v[oe]]:
                reach[v] = True
                break
    paths = []
    masks = []
    if not reach[0]:
        return paths, masks
    stack_path = []

    def dfs(node, mask):
        for oe in out_edges[node]:
            v = e_v[oe]
            if not reach[v]:
                continue
            stack_path.append(oe)
            child_mask = mask | (1 << oe)
            if v == n - 1:
                paths.append(tuple(stack_path))
                masks.append(child_mask)
                if len(paths) > MAX_PATHS:
                    raise _Invalid("too many paths")
            else:
                dfs(v, child_mask)
            stack_path.pop()

    dfs(0, 0)
    return paths, masks


def _build_output(parsed):
    n, capacity, e_u, e_v, e_ping, e_ack, e_label, rounds = parsed
    ne = len(e_u)
    out_edges = [[] for _ in range(n)]
    for i in range(ne):
        out_edges[e_u[i]].append(i)
    outdeg = [len(x) for x in out_edges]
    nr = len(rounds)
    deadlines = [rounds[r][0] + rounds[r][1] for r in range(nr)]

    metrics, state = _replay(
        n, capacity, e_u, e_v, e_ping, e_ack, rounds, out_edges, outdeg, deadlines
    )

    paths, masks = _enumerate_paths(n, out_edges, e_v)

    # Group concrete paths by telemetry signature.
    groups = {}
    for idx, path in enumerate(paths):
        sig = tuple(e_label[e] for e in path)
        bucket = groups.get(sig)
        if bucket is None:
            groups[sig] = [idx]
        else:
            bucket.append(idx)

    host_delivery = state["host_delivery"]
    proofs = state["source_proof"]
    proof_masks = {}
    for rnd in range(nr):
        if host_delivery[rnd] is None:
            continue
        mask = 0
        for e in proofs[rnd]:
            mask |= 1 << e
        proof_masks[rnd] = mask

    classes = []
    observed_classes = 0
    unique_observed = 0
    ambiguous_observed = 0
    path_evidence_upper = 0
    for sig in sorted(groups):
        idxs = groups[sig]
        count = len(idxs)
        sig_masks = [masks[i] for i in idxs]
        evidence = []
        for rnd in range(nr):
            if rnd not in proof_masks:
                continue
            pmask = proof_masks[rnd]
            for pm in sig_masks:
                if pm & pmask == pm:
                    evidence.append(rnd)
                    break
        if evidence:
            observed_classes += 1
            path_evidence_upper += count
            if count == 1:
                unique_observed += 1
            else:
                ambiguous_observed += 1
        if count == 1:
            witnesses = [list(paths[idxs[0]])]
        else:
            witnesses = [list(paths[idxs[0]]), list(paths[idxs[1]])]
        if not evidence:
            cls_state = "unobserved"
        elif count == 1:
            cls_state = "unique"
        else:
            cls_state = "ambiguous"
        classes.append(
            {
                "signature": list(sig),
                "candidate_count": count,
                "evidence_rounds": evidence,
                "state": cls_state,
                "candidate_witnesses": witnesses,
            }
        )

    observable_classes = len(classes)
    if observable_classes == 0:
        coverage = "no-routes"
    elif observed_classes == 0:
        coverage = "no-evidence"
    elif observed_classes == observable_classes:
        coverage = "complete"
    else:
        coverage = "partial"

    started = state["started"]
    final_us = state["final_us"]
    final_complete = state["final_complete"]
    proofs_by_round = state["source_proof"]
    rounds_out = []
    for rnd in range(nr):
        if started[rnd]:
            proof_set = proofs_by_round[rnd]
            proof_list = sorted(proof_set) if proof_set is not None else []
            rounds_out.append(
                {
                    "id": rnd,
                    "started": True,
                    "source_final_us": final_us[rnd],
                    "source_complete": final_complete[rnd],
                    "host_delivery_us": host_delivery[rnd],
                    "source_proof": proof_list,
                }
            )
        else:
            rounds_out.append(
                {
                    "id": rnd,
                    "started": False,
                    "source_final_us": None,
                    "source_complete": None,
                    "host_delivery_us": None,
                    "source_proof": [],
                }
            )

    summary = {
        "topology_paths": len(paths),
        "observable_classes": observable_classes,
        "observed_classes": observed_classes,
        "unique_observed_classes": unique_observed,
        "ambiguous_observed_classes": ambiguous_observed,
        "path_evidence_lower": observed_classes,
        "path_evidence_upper": path_evidence_upper,
        "coverage_status": coverage,
    }
    return {"rounds": rounds_out, "metrics": metrics, "classes": classes, "summary": summary}


def main():
    try:
        data = sys.stdin.buffer.read(MAX_INPUT_BYTES + 1)
    except Exception:
        _invalid()
    if len(data) > MAX_INPUT_BYTES:
        _invalid()
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        _invalid()
    try:
        root = json.loads(
            text, object_pairs_hook=_pairs_hook, parse_constant=_constant_hook
        )
    except _Invalid:
        _invalid()
    except Exception:
        _invalid()
    try:
        parsed = _parse(root)
    except _Invalid:
        _invalid()
    except Exception:
        _invalid()
    result = _build_output(parsed)
    sys.stdout.write(json.dumps(result, separators=(",", ":")))
    sys.stdout.write("\n")
    sys.stdout.flush()
    raise SystemExit(0)


if __name__ == "__main__":
    main()
